                     <p id="terms-error" class="error-text" hidden>Error: You must agree to the terms of use to continue.</p>
                 </div>

                 <button type="submit">Agree and Continue</button>
             </form>
         </div>
     </main>
     <script>
         document.addEventListener('DOMContentLoaded', () => {
             const form = document.getElementById('consent-form');
             const checkbox = document.getElementById('terms-consent');
             const errorText = document.getElementById('terms-error');

             form.addEventListener('submit', (event) => {
                 if (!checkbox.checked) {
                     event.preventDefault();

                     // Show error
                     errorText.hidden = false;
                     checkbox.setAttribute('aria-invalid', 'true');

                     // Move focus to checkbox
                     checkbox.focus();
                 } else {
                     // Valid submission - in a real app, this might be where you handle data
                     errorText.hidden = true;
                     checkbox.setAttribute('aria-invalid', 'false');
                     alert('Form submitted successfully!');
                 }
             });

             // Clear error when checkbox is changed
             checkbox.addEventListener('change', () => {
                 if (checkbox.checked) {
                     errorText.hidden = true;
                     checkbox.setAttribute('aria-invalid', 'false');
                 }
             });
         });
     </script>
 </body>
 </html>

